<template>
    <div class="satisfaction-chart-container" :dir="$i18n.locale === 'ar' ? 'rtl' : 'ltr'">
      <div class="satisfaction-header">
        <div class="satisfaction-filters">
          <div class="dropdown-box">
            <select v-model="selectedRegion" class="dropdown-select">
              <option value="all">{{ $t('allRegions') }}</option>
            </select>
          </div>
        </div>
        <div class="satisfaction-title">{{ $t('restaurantCategories') }}</div>
      </div>
      <div class="satisfaction-content">
        <div class="satisfaction-chart-graph-wrapper">
          <Doughnut :data="chartJsData" :options="chartOptions" class="satisfaction-chart-graph" />
        </div>
        <ul class="satisfaction-legend">
          <li class="satisfaction-legend-item" v-for="item in legendItems" :key="item.label">
            <span class="satisfaction-legend-color" :style="{ backgroundColor: item.color }"></span>
            {{ item.label }}
          </li>
        </ul>
      </div>
    </div>
  </template>
  
  <script setup>
  import { computed, ref } from 'vue'
  import { useI18n } from 'vue-i18n'
  import { Doughnut } from 'vue-chartjs'
  import {
    Chart as ChartJS,
    Title,
    Tooltip,
    Legend,
    ArcElement
  } from 'chart.js'
  
  ChartJS.register(Title, Tooltip, Legend, ArcElement)
  
  const { t } = useI18n()
  
  // Data and labels from the image
  const chartLabels = [
    t('fastFood'),
    t('familyRestaurants'),
    t('cafes'),
    t('other')
  ]
  const chartValues = [47, 40, 23, 20]
  const chartColors = ['#5B183D', '#000000', '#E5E5E5', '#BDBDBD']
  
  const legendItems = computed(() => [
    { label: t('fastFood'), color: '#5B183D' },
    { label: t('familyRestaurants'), color: '#000000' },
    { label: t('cafes'), color: '#E5E5E5' },
    { label: t('other'), color: '#BDBDBD' },
  ])
  
  const chartJsData = computed(() => ({
    labels: chartLabels,
    datasets: [
      {
        data: chartValues,
        backgroundColor: chartColors,
        borderWidth: 4
      }
    ]
  }))
  
  const chartOptions = {
    cutout: '70%',
    plugins: {
      legend: { display: false },
      tooltip: { enabled: false },
      datalabels: { display: false },
    },
  }

  const selectedRegion = ref('all')
  </script>
  
  <style scoped>
  .satisfaction-chart-container {
    background: #fff;
    padding: 1.5rem;
    border-radius: 1rem;
    display: flex;
    flex-direction: column;
    gap: 1rem;
    width: 100%;
    box-sizing: border-box;
    
    @media (max-width: 768px) {
      padding: 1.2rem;
    }
    
    @media (max-width: 480px) {
      padding: 1rem;
    }
  }
  .satisfaction-header {
    display: flex;
    flex-direction: row-reverse;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
  }
  .satisfaction-filters {
    display: flex;
    flex-direction: row-reverse;
    gap: 0.5rem;
  }
  .satisfaction-filter-btn {
    background: #f5f5f5;
    border: none;
    border-radius: 1rem;
    padding: 0.3rem 1.2rem;
    font-size: 0.95rem;
    color: #5B183D;
    cursor: pointer;
    transition: background 0.2s, color 0.2s;
  }
  .satisfaction-filter-btn.active {
    background: #5B183D;
    color: #fff;
  }
  .satisfaction-title {
    font-size: 1.1rem;
    font-weight: 600;
    color: #222;
    text-align: right;
  }
  .satisfaction-content {
    display: flex;
    flex-direction: row-reverse;
    align-items: center;
    justify-content: space-between;
    gap: 2rem;
  }
  .satisfaction-chart-graph-wrapper {
    width: 180px;
    min-width: 140px;
    display: flex;
    align-items: center;
    justify-content: center;
    
    @media (max-width: 768px) {
      width: 140px;
      min-width: 100px;
    }
    
    @media (max-width: 480px) {
      width: 120px;
      min-width: 80px;
    }
  }
  .satisfaction-chart-graph {
    width: 9rem !important;
    height: 9rem !important;
  }
  .satisfaction-legend {
    list-style: none;
    padding: 0;
    margin: 0;
    display: flex;
    flex-direction: column;
    gap: 0.7rem;
    align-items: flex-start;
  }
  .satisfaction-legend-item {
    display: flex;
    align-items: center;
    justify-content: flex-start;
    gap: 0.5rem;
    font-size: 1rem;
    color: #333;
  }
  .satisfaction-legend-color {
    width: 1.2rem;
    height: 0.7rem;
    border-radius: 2px;
    display: inline-block;
  }
  @media (max-width: 768px) {
    .satisfaction-content {
      flex-direction: column-reverse;
      gap: 1.5rem;
      align-items: stretch;
    }
    .satisfaction-chart-graph-wrapper {
      margin: 0 auto;
    }
  }

  .dropdown-select {
    padding: 6px 18px 6px 12px;
    border-radius: 9999px;
    border: 1px solid #d1d5db;
    text-align: end;
    font-size: 14px;
    background: #fff url('data:image/svg+xml;utf8,<svg fill="none" height="24" viewBox="0 0 24 24" width="24" xmlns="http://www.w3.org/2000/svg"><path d="M7 10l5 5 5-5" stroke="%235B183D" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>') no-repeat right 12px center/18px 18px;
    color: #374151;
    appearance: none;
    cursor: pointer;
    min-width: 120px;
  }
  </style> 